// The v1.1 mock data (testdata/api/v11_*.json) is generated by the builders
// below so that ~26 lectures with six stages each stay internally consistent
// (timestamps in order, usage matching durations, derived fields computed
// by derive.go). After editing a builder run:
//
//	go test ./internal/api/mockserve -run TestV11Fixtures -update
//
// TestV11Fixtures fails when the files and the builders disagree.

var updateFixtures = flag.Bool("update", false, "rewrite testdata/api/v11_*.json from fixtures_test.go")

func fixtureFiles(t *testing.T) map[string]any {
	t.Helper()
	courses, lectures := buildCoursesAndLectures(t)
	settings := buildSettings()
	usage := buildUsageToday()
	return map[string]any{
		"v11_courses.json":          courses,
		"v2_janitor_reports.json":   buildJanitorReports(courses), // janitor.go
		"v2_janitor_last_runs.json": buildJanitorLastRuns(courses),
		"v11_lectures.json":         lectures,
		"v11_settings.json":         settings,
		"v11_resources.json":        buildResources(),
		"v11_resources_nogpu.json":  buildResourcesNoGPU(),
		"v11_usage_today.json":      usage,
		"v11_dashboard.json":        buildDashboard(courses, lectures, usage, mustTime(fixtureEpoch)),
		"v11_needs_model_choice.json": api.NeedsModelChoice{
			Error: model.ErrorInfo{Code: model.ErrNeedsModelChoice},
			Diff:  diffsFor(lectures, settings, []string{lecID(c3631, 3)}, ""),
		},
	}
}

func TestV11Fixtures(t *testing.T) {
	dir := filepath.Join("..", "..", "..", "testdata", "api")
	for name, v := range fixtureFiles(t) {
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetEscapeHTML(false)
		enc.SetIndent("", " ")
		if err := enc.Encode(v); err != nil {
			t.Fatal(err)
		}
		path := filepath.Join(dir, name)
		if *updateFixtures {
			if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
				t.Fatal(err)
			}
			continue
		}
		have, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("%s: %v (run with -update)", name, err)
		}
		if !bytes.Equal(bytes.ReplaceAll(have, []byte("\r\n"), []byte("\n")), buf.Bytes()) {
			t.Errorf("%s is out of date with fixtures_test.go (run: go test ./internal/api/mockserve -run TestV11Fixtures -update)", name)
		}
	}
}

// ---------- helpers ----------

func mustTime(s string) time.Time {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		panic(err)
	}
	return t
}

func tstr(t time.Time) *string {
	s := t.UTC().Format(time.RFC3339)
	return &s
}

func sp(s string) *string    { return &s }
func i64(v int64) *int64     { return &v }
func f64(v float64) *float64 { return &v }

type price struct{ in, hit, out float64 }

var (
	priceDS = &price{2, 0.5, 8}  // CNY per million tokens
	priceAN = &price{3, 0.3, 15} // USD per million tokens
	cny     = "CNY"
	usd     = "USD"
	stagesL = model.LectureStages
)

func (p *price) usage(prompt, hit, out int64) api.UsageStats {
	u := api.UsageStats{PromptTokens: prompt, CacheHitTokens: hit, CompletionTokens: out}
	if p != nil {
		c := round4((float64(prompt-hit)*p.in + float64(hit)*p.hit + float64(out)*p.out) / 1e6)
		u.EstimatedCost = &c
	}
	return u
}

// snapshot of one LLM stage (A4.1), shown as StageModel.
type snap struct {
	providerID, providerName, model string
	temp                            float64
	window                          int
	pr                              *price
}

func (s snap) label() string {
	l := fmt.Sprintf("%s / %s · 温度 %g", s.providerName, s.model, s.temp)
	if s.window > 0 {
		l += fmt.Sprintf(" · 窗口 %d", s.window)
	}
	return l
}

// params are the snapshot's resolved params (StageModel.params; the
// example snapshots predate thinking, i.e. off).
func (s snap) params() *model.RoleParams {
	temp := s.temp
	p := &model.RoleParams{Temperature: &temp}
	if s.window > 0 {
		w := s.window
		p.Window = &w
	}
	return p
}

