func courseID(key string) string       { return "01JC000000000000000000" + key }
func lecID(key string, seq int) string { return fmt.Sprintf("01JD%s%018d", key, seq) }

// ---------- lecture builder ----------

type lb struct {
	l     api.Lecture
	clock time.Time
	snaps map[string]snap
	mins  float64 // audio length in minutes
	sents int
	asr   *asrRun // the asr run's device and timing (phase 3b); nil: cuda:0 without a timing
}

// asrRun is the device an asr run used and the worker's timing of it.
type asrRun struct {
	label, mdl, precision string
	timing                model.ASRTiming
}

// asrOn sets the device and the worker's timing (job.stats.asr_timing,
// phase 3b: the hover card's transcription time and RTF) of the lecture's
// asr run: transcription = audio length × rtf, the stage lasts load +
// transcription + 3 s (whole seconds). Call it before the asr stage is added.
func (b *lb) asrOn(label, mdl, precision string, loadMS int64, rtf float64, firstCompile bool, peakMB int) *lb {
	audio := int64(b.mins * 60000)
	b.asr = &asrRun{label: label, mdl: mdl, precision: precision, timing: model.ASRTiming{
		LoadMS: loadMS, TranscribeMS: int64(math.Round(float64(audio) * rtf)), AudioMS: audio, FirstCompile: firstCompile, PeakMemMB: peakMB}}
	return b
}

func lecture(course string, seq int, title, created string, mins float64) *lb {
	return &lb{
		l: api.Lecture{
			ID: lecID(course, seq), CourseID: courseID(course), Title: title,
			CreatedAt: *tstr(mustTime(created)), Seq: seq,
			Stages: []api.StageView{}, Exports: []api.ExportFile{},
		},
		mins:  mins,
		sents: int(mins * 11.6),
	}
}

func (b *lb) launch(at string, snaps map[string]snap) *lb {
	t := mustTime(at)
	b.l.LaunchedAt = tstr(t)
	b.clock = t
	b.snaps = snaps
	return b
}

// at moves the clock (e.g. the stages re-ran after an update).
func (b *lb) at(s string) *lb {
	b.clock = mustTime(s)
	return b
}

func (b *lb) base(stage, status string) api.StageView {
	sv := api.StageView{Stage: stage, Status: status, AllowedActions: []string{}}
	if b.l.LaunchedAt != nil {
		sv.Model = b.model(stage)
	}
	return sv
}

func (b *lb) model(stage string) *api.StageModel {
	switch stage {
	case model.StagePrep, model.StageExport:
		return nil
	case model.StageASR:
		if b.asr != nil {
			return &api.StageModel{Label: asrLabelOf(b.asr.label, b.asr.mdl, b.asr.precision, "en"), Model: b.asr.mdl}
		}
		return &api.StageModel{Label: asrLabel, Model: "large-v2"}
	}
	s := b.snaps[stage]
	return &api.StageModel{Label: s.label(), ProviderID: s.providerID, ProviderName: s.providerName, Model: s.model, Params: s.params()}
}

func (b *lb) dur(stage string) time.Duration {
	m := b.mins
	switch stage {
	case model.StagePrep:
		return time.Duration(14+m/5) * time.Second
	case model.StageASR:
		if b.asr != nil {
			return time.Duration(math.Round(float64(b.asr.timing.LoadMS+b.asr.timing.TranscribeMS)/1000)+3) * time.Second
		}
		return time.Duration(m*60/9.4) * time.Second
	case model.StageSummary:
		return time.Duration(30+m/4) * time.Second
	case model.StageRepair:
		return time.Duration(m*2.5) * time.Second
	case model.StageTranslate:
		return time.Duration(m*7.2) * time.Second
	}
	return 2 * time.Second
}

func (b *lb) usage(stage string, frac float64) api.UsageStats {
	m := b.mins * frac
	s := b.snaps[stage]
	switch stage {
	case model.StageSummary:
		return s.pr.usage(int64(240*m)+3100, 0, int64(14*m)+380)
	case model.StageRepair:
		p := int64(2100 * m)
		return s.pr.usage(p, p*76/100, int64(290*m))
	case model.StageTranslate:
		p := int64(8200 * m)
		return s.pr.usage(p, p*87/100, int64(510*m))
	}
	return api.UsageStats{}
}

func (b *lb) add(sv api.StageView) *lb {
	b.l.Stages = append(b.l.Stages, sv)
	return b
}

func (b *lb) done(stage string) *lb {
	sv := b.base(stage, model.StatusDone)
	start := b.clock.Add(2 * time.Second)
	d := b.dur(stage)
	sv.StartedAt, sv.FinishedAt = tstr(start), tstr(start.Add(d))
	sv.DurationMS = i64(d.Milliseconds())
	sv.Stats = b.usage(stage, 1)
	sv.Progress = 1
	b.clock = start.Add(d)
	if stage == model.StageASR {
		b.l.DurationMS = i64(int64(b.mins * 60000))
		if b.asr != nil {
			tm := b.asr.timing
			sv.ASRTiming = &tm
		}
	}
	return b.add(sv)
}

func (b *lb) doneAll(stages ...string) *lb {
	for _, s := range stages {
		b.done(s)
	}
	return b
}

func (b *lb) running(stage string, progress float64) *lb {
	sv := b.base(stage, model.StatusRunning)
	start := b.clock.Add(2 * time.Second)
	sv.StartedAt = tstr(start)
	sv.Progress = progress
	sv.Stats = b.usage(stage, progress)
	if stage == model.StageASR {
		s := "faster-whisper large-v2 · cuda float16"
		sv.Note = &s
	}
	return b.add(sv)
}

func (b *lb) queued(stage, waiting string) *lb {
	sv := b.base(stage, model.StatusQueued)
	sv.WaitingFor = sp(waiting)
	return b.add(sv)
}

// retryQueued: failed, now waiting for an automatic retry (SPEC §4.2).
func (b *lb) retryQueued(stage, waiting string, e *model.ErrorInfo, attempt int, ranFor time.Duration) *lb {
	sv := b.base(stage, model.StatusQueued)
	start := b.clock.Add(2 * time.Second)
	sv.StartedAt, sv.FinishedAt = tstr(start), tstr(start.Add(ranFor))
	sv.WaitingFor = sp(waiting)
	sv.Error, sv.ErrorInfo = sp(e.Detail), e
	sv.Attempt = attempt
	return b.add(sv)
}

func (b *lb) pending(stage string, waiting ...string) *lb {
	sv := b.base(stage, model.StatusPending)
	if len(waiting) > 0 {
		sv.WaitingFor = sp(waiting[0])
	}
	return b.add(sv)
}

func (b *lb) pendingRest() *lb {
	for _, s := range stagesL[len(b.l.Stages):] {
		b.pending(s)
	}
	return b
}

// failed: e is the coded error the real back end stores (v2 P14.3): the
// view's error is its detail (state.ParseJobError), error_info the code.
func (b *lb) failed(stage string, e *model.ErrorInfo, attempt int, at string, ranFor time.Duration) *lb {
	sv := b.base(stage, model.StatusFailed)
	start := mustTime(at)
	sv.StartedAt, sv.FinishedAt = tstr(start), tstr(start.Add(ranFor))
	sv.DurationMS = i64(ranFor.Milliseconds())
	sv.Error, sv.ErrorInfo = sp(e.Detail), e
	sv.Attempt = attempt
	return b.add(sv)
}

func (b *lb) cancelled(stage string, ranFor time.Duration, progress float64) *lb {
	sv := b.base(stage, model.StatusCancelled)
	start := b.clock.Add(2 * time.Second)
	sv.StartedAt, sv.FinishedAt = tstr(start), tstr(start.Add(ranFor))
	sv.DurationMS = i64(ranFor.Milliseconds())
	sv.Progress = progress
	sv.Stats = b.usage(stage, progress)
	return b.add(sv)
}

func (b *lb) stale(reason string, stages ...string) *lb {
	for _, s := range stages {
		i := stageIndex(&b.l, s)
		b.l.Stages[i].Status = model.StatusStale
		b.l.Stages[i].StaleReason = sp(reason)
	}
	return b
}

func (b *lb) counts(patches, qaFailed int) *lb {
	c := api.LectureCounts{PatchesPending: patches}
	if stageIndex(&b.l, model.StageASR) >= 0 && b.l.Stages[1].Status != model.StatusPending && b.l.Stages[1].Status != model.StatusQueued && b.l.Stages[1].Status != model.StatusRunning {
		c.Sentences = b.sents
	}
	if i := stageIndex(&b.l, model.StageTranslate); i >= 0 {
		switch st := b.l.Stages[i]; st.Status {
		case model.StatusDone, model.StatusStale:
			c.ZhOK = c.Sentences - qaFailed
			c.ZhQAFailed = qaFailed
		case model.StatusRunning:
			c.ZhOK = int(float64(c.Sentences) * st.Progress)
		}
	}
	b.l.Counts = c
	return b
}

func (b *lb) exports() *lb {
	base := b.l.Title
	n := int64(b.sents)
	files := []struct {
		suffix string
		size   int64
	}{
		{".bilingual.md", n * 236},
		{".bilingual.vtt", n * 251},
		{".zh.vtt", n * 118},
		{".en.txt", n * 104},
		{".cite.json", n * 402},
	}
	for _, f := range files {
		name := base + f.suffix
		b.l.Exports = append(b.l.Exports, api.ExportFile{Name: name, URL: "/api/lectures/" + b.l.ID + "/export/" + url.PathEscape(name), Size: f.size})
	}
	return b
}

// stream sets the playback file's state (v2 P8.1; default "ready" once playable).
func (b *lb) stream(status string) *lb {
	b.l.Stream = &api.StreamInfo{Status: status}
	return b
}

// orig sets the uploaded file name (v2 P13.3.1).
func (b *lb) orig(name string) *lb {
	b.l.OriginalFilename = name
	return b
}

// rec sets the recording time ("YYYY-MM-DDTHH:MM", local) and its source (P13.3.4).
func (b *lb) rec(at, source string) *lb {
	b.l.RecordedAt, b.l.RecordedAtSource = sp(at), source
	return b
}

// kind sets a kind that did not come from the file name (lecture kinds,
// kinds.go): the model's judgement (llm) or the user's.
func (b *lb) kind(id, source string) *lb {
	b.l.Kind, b.l.KindSource = id, source
	return b
}

// titleFailed adds a failed title task (P13.5: shown on the lecture page with retry).
func (b *lb) titleFailed(at, detail string) *lb {
	st := api.StageView{Stage: model.StageTitle, Status: model.StatusFailed, AllowedActions: []string{model.ActionRetry}, DisplayStatus: model.StatusFailed,
		Error: sp(detail), ErrorInfo: &model.ErrorInfo{Code: "title.invalid_output", Detail: detail}, Attempt: 1}
	st.StartedAt, st.FinishedAt, st.DurationMS = tstr(mustTime(at)), tstr(mustTime(at).Add(7*time.Second)), i64(7000)
	b.l.Aux = append(b.l.Aux, st)
	return b
}

// named sets what the title task wrote (P13.5): titles and blurbs, source llm.
func (b *lb) named(en, zh, blurbEn, blurbZh string) *lb {
	b.l.Title, b.l.TitleZh, b.l.TitleSource = en, sp(zh), model.TitleSourceLLM
	b.l.BlurbEn, b.l.BlurbZh = sp(blurbEn), sp(blurbZh)
	return b
}

func (b *lb) build(t *testing.T) api.Lecture {
	t.Helper()
	if len(b.l.Stages) != len(stagesL) {
		t.Fatalf("%s: %d stages", b.l.Title, len(b.l.Stages))
	}
	for i, st := range b.l.Stages {
		if st.Stage != stagesL[i] {
			t.Fatalf("%s: stage %d is %s", b.l.Title, i, st.Stage)
		}
	}
	finalizeLecture(&b.l)
	return b.l
}

func draft(course string, seq int, title, created string, mins float64) *lb {
	b := lecture(course, seq, title, created, mins)
	for _, s := range stagesL {
		b.pending(s)
	}
	return b
}

