// fixtureRule is the rule the mock's organizer wrote for a course (mockRules).
func fixtureRule(code, created string, matched, total int) *api.FilenameRule {
	return &api.FilenameRule{Regex: mockRules[code].regex, Source: "llm", CreatedAt: created, SamplesMatched: matched, SamplesTotal: total}
}

// janitorDone adds a finished glossary_review (Anthropic / claude-opus-5-5)
// and the Janitor status of its report (G3.5).
func janitorDone(c *api.Course, started string, ran time.Duration, changes int) {
	start := mustTime(started)
	st := api.StageView{Stage: model.StageGlossaryReview, Status: model.StatusDone, Progress: 1, AllowedActions: []string{model.ActionRerun}, DisplayStatus: model.StatusDone}
	st.StartedAt, st.FinishedAt, st.DurationMS = tstr(start), tstr(start.Add(ran)), i64(ran.Milliseconds())
	st.Stats = priceAN.usage(21400, 0, 2900)
	c.Stages = append(c.Stages, st)
	c.Janitor = api.JanitorStatus{Configured: true, LastAt: *tstr(start.Add(ran)), LastModel: "Anthropic / claude-opus-5-5", LastVersion: c.GlossaryVersion, LastChanges: changes}
}

func course(key, code, name, created string, glossV, terms int, syl *api.Syllabus, mats []api.Material) api.Course {
	c := api.Course{
		ID: courseID(key), Name: name, CreatedAt: *tstr(mustTime(created)),
		GlossaryVersion: glossV, Syllabus: syl, TermCount: terms,
		Stages: []api.StageView{}, Materials: mats, CourseActions: []string{},
	}
	if code != "" {
		c.Code = sp(code)
	}
	if syl != nil {
		start := mustTime(created).Add(3 * time.Minute)
		st := api.StageView{Stage: model.StageGlossarySeed, Status: model.StatusDone, Progress: 1, AllowedActions: []string{model.ActionRerun}, DisplayStatus: model.StatusDone}
		st.StartedAt, st.FinishedAt = tstr(start), tstr(start.Add(41*time.Second))
		st.DurationMS = i64(41000)
		st.Stats = priceDS.usage(int64(syl.Chars/3)+2400, 0, 3900)
		if key == cRM {
			st.Status, st.DisplayStatus, st.Progress = model.StatusRunning, model.StatusRunning, 0.35
			st.FinishedAt, st.DurationMS = nil, nil
			st.Stats = api.UsageStats{}
			st.AllowedActions = []string{model.ActionCancel}
		}
		c.Stages = []api.StageView{st}
	}
	return c
}

// bindWeek binds slides to a teaching week chosen by hand (lecture kinds).
func bindWeek(m api.Material, week int) api.Material {
	m.Bind = &api.MaterialBind{Scope: api.BindWeek, Week: &week}
	return m
}

// textIncomplete marks a slide file whose text could probably not be
// extracted in full (v3 V6: many empty pages).
func textIncomplete(m api.Material) api.Material {
	m.TextWarning = api.TextWarningIncomplete
	return m
}

func material(course, suffix string, lectureID *string, filename string, pages int, created string, termsDone bool) api.Material {
	m := api.Material{
		ID: "01JM0000000000000000" + course + "0" + suffix, CourseID: courseID(course), LectureID: lectureID,
		Filename: filename, Pages: pages, CreatedAt: *tstr(mustTime(created)), CanDelete: termsDone,
		Bind: defaultBind(lectureID, filename), // lecture kinds (kinds.go)
	}
	start := mustTime(created).Add(5 * time.Second)
	ex := api.StageView{Stage: model.StageMaterialExtract, Status: model.StatusDone, Progress: 1, AllowedActions: []string{model.ActionRerun}, DisplayStatus: model.StatusDone}
	ex.StartedAt, ex.FinishedAt, ex.DurationMS = tstr(start), tstr(start.Add(9*time.Second)), i64(9000)
	tm := api.StageView{Stage: model.StageMaterialTerms, Status: model.StatusDone, Progress: 1, AllowedActions: []string{model.ActionRerun}, DisplayStatus: model.StatusDone}
	tm.StartedAt = tstr(start.Add(12 * time.Second))
	if termsDone {
		tm.FinishedAt, tm.DurationMS = tstr(start.Add(48*time.Second)), i64(36000)
		tm.Stats = priceDS.usage(int64(pages)*820, 0, 2600)
	} else {
		tm.Status, tm.DisplayStatus, tm.Progress = model.StatusRunning, model.StatusRunning, 0.6
		tm.AllowedActions = []string{model.ActionCancel}
	}
	m.Stages = []api.StageView{ex, tm}
	return m
}

